import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        int mid = n / 2;
        List<Integer> sumsLeft = new ArrayList<>();
        List<Integer> sumsRight = new ArrayList<>();

        generateLeft(0, 0, a, mid, m, sumsLeft);
        generateRight(mid, 0, a, n, m, sumsRight);

        Set<Integer> setSumsLeft = new HashSet<>(sumsLeft);
        List<Integer> uniqueSumsLeft = new ArrayList<>(setSumsLeft);
        Collections.sort(uniqueSumsLeft);

        int maxFound = 0;

        for (int val : sumsRight) {
            int j = Collections.binarySearch(uniqueSumsLeft, m - val);
            if (j < 0) {
                j = -j - 1;
            }
            if (j > 0) {
                int candidate = uniqueSumsLeft.get(j - 1) + val;
                if (candidate > maxFound) {
                    maxFound = candidate;
                }
            }
        }
        System.out.println(maxFound);
    }

    private static void generateLeft(int i, int total, int[] a, int mid, int m, List<Integer> sumsLeft) {
        if (i == mid) {
            sumsLeft.add(total % m);
        } else {
            generateLeft(i + 1, total + a[i], a, mid, m, sumsLeft);
            generateLeft(i + 1, total, a, mid, m, sumsLeft);
        }
    }

    private static void generateRight(int i, int total, int[] a, int n, int m, List<Integer> sumsRight) {
        if (i == n) {
            sumsRight.add(total % m);
        } else {
            generateRight(i + 1, total + a[i], a, n, m, sumsRight);
            generateRight(i + 1, total, a, n, m, sumsRight);
        }
    }
}
